from collections import defaultdict

# 元素顺序（按表中列顺序）
elems = ['e','α','η','β','γ','ζ','ε','δ']
idx = {name:i for i,name in enumerate(elems)}

# 乘法表（行 × 列）
table = [
    ['e','α','η','β','γ','ζ','ε','δ'],  # e
    ['α','η','β','e','ζ','ε','δ','γ'],  # α
    ['η','β','e','α','ε','δ','γ','ζ'],  # η
    ['β','e','α','η','δ','γ','ζ','ε'],  # β
    ['γ','ζ','ε','δ','e','α','η','β'],  # γ
    ['ζ','ε','δ','γ','α','η','β','e'],  # ζ
    ['ε','δ','γ','ζ','η','β','e','α'],  # ε
    ['δ','γ','ζ','ε','β','e','α','η'],  # δ
]

def mul(a,b):
    return table[idx[a]][idx[b]]

def inv(a):
    for b in elems:
        if mul(a,b)=='e' and mul(b,a)=='e':
            return b
    raise ValueError

# 1) 验证结合律（穷举）
print("验证结合律...")
ok = True
for a in elems:
    for b in elems:
        for c in elems:
            if mul(mul(a,b),c) != mul(a,mul(b,c)):
                ok = False
                print(f"  结合律失败: {a},{b},{c}")
print(f"  结合律: {'PASS' if ok else 'FAIL'}")

# 2) 检查交换性
abelian = True
for a in elems:
    for b in elems:
        if mul(a,b) != mul(b,a):
            abelian = False
            break
print(f"交换群: {abelian}")

# 3) 各元素阶
print("\n元素阶:")
for a in elems:
    p = a
    for k in range(1,9):
        if p == 'e':
            print(f"  {a}: order {k}")
            break
        p = mul(p,a)

# 4) 共轭类
print("\n共轭类计算:")
conj = defaultdict(set)
for a in elems:
    for g in elems:
        b = mul(mul(g,a), inv(g))
        conj[a].add(b)

classes = []
seen = set()
for a in elems:
    if a not in seen:
        cls = frozenset(conj[a])
        classes.append(cls)
        seen |= cls

for i,cls in enumerate(classes):
    print(f"  C{i+1} = {{{', '.join(sorted(cls))}}}")

print(f"\n共轭类个数: {len(classes)}")
